{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE redtape_db.Maplemonk.redtape_db_myntra_margin_fact_items as SELECT EAN ,MYT.BRAND BRAND ,MYT.GENDER GENDER ,\"TARGET_DIS%\" ,\"REBATE%\" ,ROUND(BILL_VALUE ,2) BILL_VALUE ,REBATE_VALUE ,SKU ,ARTICLE ,UPPER(CATEGORY_NAME) CATEGORY ,SAP_CATEGORY ,MYT.ARTICLE_TYPE ARTICLE_TYPE ,TYPE ,LEVEL ,AVAILABLE_QUANTITY ,CODE ,MRP ,COST ,MULTIPLE ,GT_CHARGES ,ROUND(BILL_VALUE_AFTER_GT,2) BILL_VALUE_AFTER_GT ,CASE WHEN BILL_VALUE_AFTER_GT < 2625 THEN 5 ELSE 18 END AS \"GST_%\" ,ROUND((BILL_VALUE_AFTER_GT * 100 / NULLIF(100 + \"GST_%\", 0)),2) AS SALE_VALUE_AFTER_GT ,COALESCE((SALE_VALUE_AFTER_GT + REBATE_VALUE),0) AS SALE_VALUE_REBATE ,ROUND(COALESCE(SALE_VALUE_REBATE, 0) - COALESCE(COST, 0),2) AS GROSS_MARGIN ,ROUND((GROSS_MARGIN / NULLIF(SALE_VALUE_REBATE, 0)) * 100,2) AS \"GROSS_MARGIN%\" ,COALESCE(COMM_PERCENT,DEFAULT_PERCENT,0) COMM_PERCENT ,((COALESCE(COMM_PERCENT,0) / 118) * 100) \"COMMISSION%\" ,ROUND((BILL_VALUE_AFTER_GT * (COALESCE(\"COMMISSION%\", 0) / 100)),2) AS COMMISSION_VALUE ,ROUND((COALESCE(FF.AMOUNT,0)*(100-\"COURIER_RET%\")/100)/ NULLIF((100-\"COURIER_RET%\"-\"CUSTOMER_RET%\")/100,0),2) AS FIXED_FEE ,Reverse_Frieght ,REV_FRT ,\"COURIER_RET%\" ,\"CUSTOMER_RET%\" ,ROUND(7 / NULLIF((100-\"COURIER_RET%\"-\"CUSTOMER_RET%\")/100,0),2) AS PACKING ,ROUND((COALESCE(BILL_VALUE_AFTER_GT,0)*(3/100)),2) AS ADVERTISEMET ,ROUND((COALESCE(SALE_VALUE_AFTER_GT,0)*(7.5/100)),2) AS COMMON ,ROUND(COALESCE(COMMISSION_VALUE,0)+COALESCE(FIXED_FEE,0)+COALESCE(REV_FRT,0)+COALESCE(PACKING,0)+COALESCE(ADVERTISEMET,0)+COALESCE(COMMON,0),2) AS TOTAL_EXPENSES ,ROUND(COALESCE(GROSS_MARGIN,0) - COALESCE(TOTAL_EXPENSES,0),2) AS NET_MARGIN ,ROUND(COALESCE(NET_MARGIN,0) / NULLIF(SALE_VALUE_REBATE,0) * 100,2) AS \"NET_MARGIN%\" ,ROUND(NET_MARGIN + COALESCE(REBATE_VALUE,0),2) AS NET_MARGIN_AFTER_REBATE ,ROUND( NET_MARGIN_AFTER_REBATE / NULLIF(SALE_VALUE_REBATE/100,0),2) AS \"NET_MARGIN%_2\" FROM( SELECT ISN.GENDER GENDER ,EAN ,ISN.BRAND ,\"TARGET_DIS%\" ,\"REBATE%\" ,COALESCE(ISN.MRP,0) - (COALESCE(ISN.MRP,0)* \"TARGET_DIS%\" / 100) AS BILL_VALUE ,CASE WHEN BILL_VALUE < 100 THEN 1 WHEN BILL_VALUE < 501 THEN 83 WHEN BILL_VALUE < 1001 THEN 118 WHEN BILL_VALUE < 2001 THEN 195 ELSE 230 END AS GT_CHARGES ,COALESCE(BILL_VALUE,0) - COALESCE(GT_CHARGES,0) AS BILL_VALUE_AFTER_GT ,ROUND((BILL_VALUE*(\"REBATE%\"/100)),2) AS REBATE_VALUE ,UPPER(ISN.SKU) SKU ,UPPER(ISN.ARTICLES) ARTICLE ,ISN.MYNTRA_CATEGORY ARTICLE_TYPE ,ISN.TYPE ,ISN.CATEGORY_NAME ,ISN.SAP_CATEGORY ,ISN.LEVEL ,AVAILABLE_QUANTITY ,ISN.CODE ,COALESCE(ISN.MRP,0) MRP ,ISN.COST ,ROUND(COALESCE(ISN.MRP,0) / NULLIF(ISN.COST, 0),2) AS MULTIPLE ,\"COURIER_RET%\" ,\"CUSTOMER_RET%\" ,Reverse_Frieght ,ROUND(((Reverse_Frieght*(\"CUSTOMER_RET%\"/100))/((100 - \"COURIER_RET%\" - \"CUSTOMER_RET%\")/100)),2) AS REV_FRT FROM ( SELECT COALESCE(A.EANUPC,REPLACE(B.EAN, \'`\', \'\')) EAN, A.SKU, A.ARTICLES, A.TYPE, CAST(REPLACE(A.COST, \',\', \'\') AS FLOAT) AS COST, CAST(REPLACE(A.MRP, \',\', \'\') AS FLOAT) AS MRP, A.LEVEL, A.BRAND, A.GENDER, UPPER(A.SAP_CATEGORY) SAP_CATEGORY, A.CATEGORY_NAME, A.MYNTRA_CATEGORY, REGEXP_SUBSTR(ARTICLES, \'^[A-Z]{3}\') AS CODE, 80.0 AS \"TARGET_DIS%\", 18.0 \"REBATE%\", CASE WHEN \"Courier Return %\" IS NULL OR \"Courier Return %\" = 0 THEN 21 ELSE ROUND(\"Courier Return %\", 1) END AS \"COURIER_RET%\", CASE WHEN \"Customer Return %\" IS NULL OR \"Customer Return %\" = 0 THEN 13 ELSE ROUND(\"Customer Return %\", 1)END AS \"CUSTOMER_RET%\", ( (r.local * z.local/100) + (r.zonal * z.zonal/100) + (r.national * z.national/100) ) AS reverse_frieght, B.AVAILABLE_QUANTITY FROM MAPLEMONK.REDTAPE_DB_MARGIN_PRODUCT_MASTER A LEFT JOIN( SELECT * FROM ( SELECT \"Report Generated Date\"::DATE AS FIRST_DATE ,REPLACE(EAN, \'`\', \'\') AS EAN ,SUM(\"Available Quantity\") AS AVAILABLE_QUANTITY FROM REDTAPE_DB.MAPLEMONK.EASYECOM_REDTAPE_INVENTORY_SNAPSHOT WHERE \"Report Generated Date\" IS NOT NULL GROUP BY 1,2) QUALIFY ROW_NUMBER() OVER(PARTITION BY EAN ORDER BY FIRST_DATE DESC) = 1) B ON REPLACE(A.EANUPC, \'`\', \'\') = REPLACE(B.EAN, \'`\', \'\') LEFT JOIN( SELECT \"TYPE 2\" TYPE ,GENDER ,\"Courier Return %\" ,\"Customer Return %\" FROM MAPLEMONK.REDTAPE_MYNTRA_MARGIN_RETURN__ where UPPER(gender) != \'ALL\') CR ON UPPER(REPLACE(TRIM(A.TYPE), \' \', \'\')) = UPPER(REPLACE(TRIM(CR.TYPE), \' \', \'\')) AND UPPER(TRIM(A.GENDER)) = UPPER(TRIM(CR.GENDER)) LEFT JOIN ( SELECT level, local, zonal, national FROM MAPLEMONK.REDTAPE_MYNTRA_MARGIN_RETURN_FEE ) r ON lower(A.level) = lower(r.level) LEFT JOIN ( SELECT remarks, (CAST(REPLACE(local,\'%\',\'\') AS FLOAT)) local, (CAST(REPLACE(zonal,\'%\',\'\') AS FLOAT)) zonal, (CAST(REPLACE(national,\'%\',\'\') AS FLOAT)) national FROM MAPLEMONK.REDTAPE_MYNTRA_MARGIN_ZONES_SHARE__ ) z ON 1=1 ) ISN )MYT LEFT JOIN ( SELECT AMOUNT ,SELLING_PRICE_LOWER ,SELLING_PRICE_UPPER FROM MAPLEMONK.REDTAPE_MYNTRA_MARGIN_FIXED_FEE) FF ON MYT.BILL_VALUE_AFTER_GT BETWEEN FF.SELLING_PRICE_LOWER AND FF.SELLING_PRICE_UPPER LEFT JOIN( SELECT BRAND, \"Master Category\" AS MASTER_CATEGORY, \"Article Type\" AS ARTICLE_TYPE, GENDER, \"Minimum Commission(Rs.)\" AS MIN_COMMISSION, \"Default Commission (%)\" AS DEFAULT_PERCENT, LOWER_LIMIT, UPPER_LIMIT, CAST(COMM_PERCENT AS FLOAT) COMM_PERCENT FROM ( SELECT BRAND,\"Master Category\",\"Article Type\",GENDER, \"Minimum Commission(Rs.)\", \"Default Commission (%)\", \"Commission Slab 1 Lower Limit(Rs.)\" LOWER_LIMIT, \"Commission Slab 1 Upper Limit(Rs.)\" UPPER_LIMIT, \"Commission Slab 1 Commission(%)\" COMM_PERCENT from maplemonk.redtape_myntra_margin_commission UNION ALL SELECT BRAND,\"Master Category\",\"Article Type\",GENDER, \"Minimum Commission(Rs.)\", \"Default Commission (%)\", \"Commission Slab 2 Lower Limit(Rs.)\", \"Commission Slab 2 Upper Limit(Rs.)\", \"Commission Slab 2 Commission(%)\" from maplemonk.redtape_myntra_margin_commission UNION ALL SELECT BRAND,\"Master Category\",\"Article Type\",GENDER, \"Minimum Commission(Rs.)\", \"Default Commission (%)\", \"Commission Slab 3 Lower Limit(Rs.)\", \"Commission Slab 3 Upper Limit(Rs.)\", \"Commission Slab 3 Commission(%)\" from maplemonk.redtape_myntra_margin_commission UNION ALL SELECT BRAND,\"Master Category\",\"Article Type\",GENDER, \"Minimum Commission(Rs.)\", \"Default Commission (%)\", \"Commission Slab 4 Lower Limit(Rs.)\", \"Commission Slab 4 Upper Limit(Rs.)\", \"Commission Slab 4 Commission(%)\" from maplemonk.redtape_myntra_margin_commission UNION ALL SELECT BRAND,\"Master Category\",\"Article Type\",GENDER, \"Minimum Commission(Rs.)\", \"Default Commission (%)\", \"Commission Slab 5 Lower Limit(Rs.)\", \"Commission Slab 5 Upper Limit(Rs.)\", \"Commission Slab 5 Commission(%)\" from maplemonk.redtape_myntra_margin_commission) ) comm ON UPPER(REPLACE(TRIM(COMM.BRAND),\' \',\'\')) = UPPER(REPLACE(TRIM(MYT.BRAND),\' \',\'\')) AND UPPER(REPLACE(TRIM(COMM.ARTICLE_TYPE),\' \',\'\')) = UPPER(REPLACE(TRIM(MYT.ARTICLE_TYPE),\' \',\'\')) AND UPPER(REPLACE(TRIM(COMM.GENDER),\' \',\'\')) = UPPER(REPLACE(TRIM(MYT.GENDER),\' \',\'\')) AND MYT.BILL_VALUE_AFTER_GT >= COMM.LOWER_LIMIT AND MYT.BILL_VALUE_AFTER_GT < COMM.UPPER_LIMIT;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from REDTAPE_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            